using System.Reflection;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

public class LayerDependencyTests
{
    private const string Domain = "PaymentAuthorization.Domain";
    private const string Application = "PaymentAuthorization.Application";
    private const string Infrastructure = "PaymentAuthorization.Infrastructure";

    [Theory]
    [InlineData(Domain, Application)]
    [InlineData(Domain, Infrastructure)]
    [InlineData(Application, Infrastructure)]
    public void Layer_does_not_depend_on_outer_layer(string inner, string outer)
    {
        var assembly = Load(inner);
        var references = assembly.GetReferencedAssemblies().Select(a => a.Name);

        Assert.DoesNotContain(outer, references);
    }

    [Theory]
    [InlineData(Domain)]
    [InlineData(Application)]
    public void Inner_layer_uses_no_third_party_packages(string layer)
    {
        var offending = Load(layer).GetReferencedAssemblies()
            .Select(a => a.Name!)
            .Where(n => !n.StartsWith("System", StringComparison.Ordinal)
                     && n != "netstandard" && n != "mscorlib"
                     && !n.StartsWith("PaymentAuthorization.", StringComparison.Ordinal))
            .ToList();

        Assert.Empty(offending);
    }

    private static Assembly Load(string name) => name switch
    {
        Domain => typeof(Money).Assembly,
        Application => typeof(AuthorizePayment).Assembly,
        Infrastructure => typeof(FileSystemReceiptStore).Assembly,
        _ => throw new ArgumentOutOfRangeException(nameof(name)),
    };
}
